(function(){
  const COLS = 10;
  const ROWS = 20;
  const BLOCK = 30;
  const COLORS = {
    I: '#06b6d4',
    O: '#eab308',
    T: '#a855f7',
    S: '#22c55e',
    Z: '#ef4444',
    J: '#3b82f6',
    L: '#f97316'
  };
  const GHOST_ALPHA = 0.25;

  const SHAPES = {
    I: [[0,0],[1,0],[2,0],[3,0]],
    O: [[0,0],[1,0],[0,1],[1,1]],
    T: [[0,0],[1,0],[2,0],[1,1]],
    S: [[1,0],[2,0],[0,1],[1,1]],
    Z: [[0,0],[1,0],[1,1],[2,1]],
    J: [[0,0],[0,1],[1,1],[2,1]],
    L: [[2,0],[0,1],[1,1],[2,1]]
  };

  const canvas = document.getElementById('board');
  const ctx = canvas.getContext('2d');
  const nextCanvas = document.getElementById('next-piece');
  const nextCtx = nextCanvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const levelEl = document.getElementById('level');
  const linesEl = document.getElementById('lines');
  const overlay = document.getElementById('overlay');
  const overlayText = document.getElementById('overlay-text');
  const startBtn = document.getElementById('start-btn');

  let board, currentPiece, nextPiece, score, level, linesCleared, gameOver, paused, dropInterval, lastDrop, animFrame;

  function createBoard(){
    return Array.from({length:ROWS}, ()=> Array(COLS).fill(null));
  }

  function randomType(){
    const types = Object.keys(SHAPES);
    return types[Math.floor(Math.random()*types.length)];
  }

  function createPiece(type){
    const cells = SHAPES[type].map(c => [c[0], c[1]]);
    const px = Math.floor((COLS - 4)/2);
    return {
      type,
      cells: cells.map(c => [c[0]+px, c[1]]),
      color: COLORS[type]
    };
  }

  function rotatePiece(piece){
    const cx = piece.cells.reduce((s,c)=>s+c[0],0)/4;
    const cy = piece.cells.reduce((s,c)=>s+c[1],0)/4;
    const newCells = piece.cells.map(([x,y])=>{
      const dx = x - cx;
      const dy = y - cy;
      return [Math.round(cx - dy), Math.round(cy + dx)];
    });
    return {...piece, cells: newCells};
  }

  function isValid(cells){
    return cells.every(([x,y]) => x>=0 && x<COLS && y<ROWS && (y<0 || !board[y][x]));
  }

  function placePiece(){
    currentPiece.cells.forEach(([x,y])=>{
      if(y>=0) board[y][x] = currentPiece.color;
    });
    clearLines();
    currentPiece = createPiece(nextPiece);
    nextPiece = randomType();
    if(!isValid(currentPiece.cells)){
      gameOver = true;
      overlayText.textContent = 'Game Over — Score: ' + score;
      startBtn.textContent = 'Restart';
      overlay.classList.remove('hidden');
    }
  }

  function clearLines(){
    let cleared = 0;
    for(let r = ROWS-1; r>=0; r--){
      if(board[r].every(c => c !== null)){
        board.splice(r, 1);
        board.unshift(Array(COLS).fill(null));
        cleared++;
        r++;
      }
    }
    if(cleared > 0){
      const pts = [0, 100, 300, 500, 800];
      score += (pts[cleared] || 800) * level;
      linesCleared += cleared;
      level = Math.floor(linesCleared / 10) + 1;
      dropInterval = Math.max(50, 1000 - (level-1)*80);
      updateUI();
    }
  }

  function updateUI(){
    scoreEl.textContent = score;
    levelEl.textContent = level;
    linesEl.textContent = linesCleared;
  }

  function getGhostY(){
    let offset = 0;
    while(true){
      const moved = currentPiece.cells.map(([x,y])=>[x,y+offset+1]);
      if(!isValid(moved)) break;
      offset++;
    }
    return offset;
  }

  function drawBlock(context, x, y, color, size, alpha){
    context.globalAlpha = alpha || 1;
    context.fillStyle = color;
    context.fillRect(x*size, y*size, size, size);
    context.strokeStyle = 'rgba(255,255,255,0.15)';
    context.lineWidth = 1;
    context.strokeRect(x*size+.5, y*size+.5, size-1, size-1);
    context.globalAlpha = 1;
  }

  function drawGrid(){
    ctx.strokeStyle = 'rgba(255,255,255,0.04)';
    ctx.lineWidth = 1;
    for(let r=0;r<ROWS;r++){
      for(let c=0;c<COLS;c++){
        ctx.strokeRect(c*BLOCK+.5, r*BLOCK+.5, BLOCK-1, BLOCK-1);
      }
    }
  }

  function draw(){
    const w = canvas.width;
    const h = canvas.height;
    ctx.clearRect(0,0,w,h);
    ctx.fillStyle = '#0f172a';
    ctx.fillRect(0,0,w,h);
    drawGrid();

    // board
    for(let r=0;r<ROWS;r++){
      for(let c=0;c<COLS;c++){
        if(board[r][c]) drawBlock(ctx, c, r, board[r][c], BLOCK);
      }
    }

    if(currentPiece && !gameOver){
      // ghost
      const ghostOffset = getGhostY();
      currentPiece.cells.forEach(([x,y])=>{
        if(y+ghostOffset>=0) drawBlock(ctx, x, y+ghostOffset, currentPiece.color, BLOCK, GHOST_ALPHA);
      });
      // piece
      currentPiece.cells.forEach(([x,y])=>{
        if(y>=0) drawBlock(ctx, x, y, currentPiece.color, BLOCK);
      });
    }

    // next piece preview
    const ns = 30;
    nextCtx.clearRect(0,0,nextCanvas.width,nextCanvas.height);
    nextCtx.fillStyle = '#0f172a';
    nextCtx.fillRect(0,0,nextCanvas.width,nextCanvas.height);
    if(nextPiece){
      const shape = SHAPES[nextPiece];
      const minX = Math.min(...shape.map(c=>c[0]));
      const maxX = Math.max(...shape.map(c=>c[0]));
      const minY = Math.min(...shape.map(c=>c[1]));
      const maxY = Math.max(...shape.map(c=>c[1]));
      const pw = maxX - minX + 1;
      const ph = maxY - minY + 1;
      const ox = Math.floor((4 - pw)/2);
      const oy = Math.floor((4 - ph)/2);
      shape.forEach(([x,y])=>{
        drawBlock(nextCtx, x - minX + ox, y - minY + oy, COLORS[nextPiece], ns);
      });
    }
  }

  function move(dx, dy){
    const moved = currentPiece.cells.map(([x,y])=>[x+dx, y+dy]);
    if(isValid(moved)){
      currentPiece.cells = moved;
      return true;
    }
    return false;
  }

  function rotate(){
    const rotated = rotatePiece(currentPiece);
    if(isValid(rotated.cells)){
      currentPiece.cells = rotated.cells;
      return;
    }
    // wall kicks
    for(const kick of [-1,1,-2,2]){
      const kicked = rotated.cells.map(([x,y])=>[x+kick,y]);
      if(isValid(kicked)){
        currentPiece.cells = kicked;
        return;
      }
    }
  }

  function hardDrop(){
    const offset = getGhostY();
    currentPiece.cells = currentPiece.cells.map(([x,y])=>[x,y+offset]);
    score += offset * 2;
    updateUI();
    placePiece();
  }

  function gameLoop(time){
    if(gameOver) return;
    if(!paused){
      if(time - lastDrop > dropInterval){
        if(!move(0,1)){
          placePiece();
        }
        lastDrop = time;
      }
      draw();
    }
    animFrame = requestAnimationFrame(gameLoop);
  }

  function startGame(){
    board = createBoard();
    score = 0;
    level = 1;
    linesCleared = 0;
    gameOver = false;
    paused = false;
    dropInterval = 1000;
    lastDrop = 0;
    nextPiece = randomType();
    currentPiece = createPiece(randomType());
    updateUI();
    overlay.classList.add('hidden');
    if(animFrame) cancelAnimationFrame(animFrame);
    animFrame = requestAnimationFrame(gameLoop);
  }

  function togglePause(){
    if(gameOver) return;
    paused = !paused;
    if(paused){
      overlayText.textContent = 'Paused';
      startBtn.textContent = 'Resume';
      overlay.classList.remove('hidden');
    } else {
      overlay.classList.add('hidden');
      lastDrop = performance.now();
      animFrame = requestAnimationFrame(gameLoop);
    }
  }

  startBtn.addEventListener('click', ()=>{
    if(paused){
      togglePause();
    } else {
      startGame();
    }
  });

  document.addEventListener('keydown', (e)=>{
    if(gameOver && e.key !== ' ') return;
    switch(e.key){
      case 'ArrowLeft':
        e.preventDefault();
        if(!paused) move(-1,0);
        break;
      case 'ArrowRight':
        e.preventDefault();
        if(!paused) move(1,0);
        break;
      case 'ArrowDown':
        e.preventDefault();
        if(!paused){
          if(move(0,1)) { score += 1; updateUI(); }
        }
        break;
      case 'ArrowUp':
        e.preventDefault();
        if(!paused) rotate();
        break;
      case ' ':
        e.preventDefault();
        if(!paused && !gameOver) hardDrop();
        break;
      case 'p':
      case 'P':
        togglePause();
        break;
    }
  });

  // Mobile controls
  document.getElementById('btn-left').addEventListener('click', ()=>{ if(!paused && !gameOver) move(-1,0); });
  document.getElementById('btn-right').addEventListener('click', ()=>{ if(!paused && !gameOver) move(1,0); });
  document.getElementById('btn-rotate').addEventListener('click', ()=>{ if(!paused && !gameOver) rotate(); });
  document.getElementById('btn-down').addEventListener('click', ()=>{ if(!paused && !gameOver){ if(move(0,1)){score+=1;updateUI();} } });
  document.getElementById('btn-drop').addEventListener('click', ()=>{ if(!paused && !gameOver) hardDrop(); });

  // Scale canvas for mobile
  function resizeCanvas(){
    const bw = canvas.parentElement.clientWidth - 4; // subtract border
    if(window.innerWidth <= 768){
      const scale = Math.min(bw / (COLS * BLOCK), 1);
      canvas.style.width = (COLS * BLOCK * scale) + 'px';
      canvas.style.height = (ROWS * BLOCK * scale) + 'px';
    } else {
      canvas.style.width = '';
      canvas.style.height = '';
    }
  }
  window.addEventListener('resize', resizeCanvas);
  resizeCanvas();

  draw();
})();

*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}

body{
  font-family:system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;
  background:#f8fafc;
  color:#0f172a;
  font-size:1rem;
  line-height:1.65;
  min-height:100vh;
}

.container{
  max-width:1100px;
  margin:0 auto;
  padding:24px 16px;
}

header{
  text-align:center;
  margin-bottom:32px;
}

h1{
  font-size:clamp(2.5rem,6vw,4.5rem);
  font-weight:800;
  letter-spacing:-0.04em;
  color:#4F46E5;
}

.game-layout{
  display:flex;
  justify-content:center;
  align-items:flex-start;
  gap:24px;
}

.side-panel{
  display:flex;
  flex-direction:column;
  gap:16px;
  min-width:130px;
}

.info-box{
  background:#fff;
  border:1px solid #e2e8f0;
  border-radius:12px;
  padding:16px;
  box-shadow:0 1px 3px rgba(0,0,0,.06);
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:8px;
}

.info-box .label, .controls-info .label{
  font-size:.75rem;
  font-weight:600;
  text-transform:uppercase;
  letter-spacing:.08em;
  color:#64748b;
}

.info-box .value{
  font-size:1.75rem;
  font-weight:800;
  color:#4F46E5;
}

.controls-info{
  background:#fff;
  border:1px solid #e2e8f0;
  border-radius:12px;
  padding:16px;
  box-shadow:0 1px 3px rgba(0,0,0,.06);
}

.controls-info ul{
  list-style:none;
  margin-top:8px;
  display:flex;
  flex-direction:column;
  gap:4px;
  font-size:.85rem;
}

kbd{
  display:inline-block;
  background:#f1f5f9;
  border:1px solid #e2e8f0;
  border-radius:4px;
  padding:2px 6px;
  font-size:.75rem;
  font-weight:600;
  font-family:inherit;
}

.board-wrapper{
  position:relative;
  border-radius:12px;
  overflow:hidden;
  box-shadow:0 4px 24px rgba(79,70,229,.15);
  border:2px solid #4F46E5;
  line-height:0;
}

#board{
  display:block;
  background:#0f172a;
}

.overlay{
  position:absolute;
  inset:0;
  background:rgba(15,23,42,.85);
  display:flex;
  align-items:center;
  justify-content:center;
  z-index:10;
  transition:opacity .3s;
}

.overlay.hidden{
  opacity:0;
  pointer-events:none;
}

.overlay-content{
  text-align:center;
  color:#fff;
}

.overlay-content p{
  font-size:1.25rem;
  font-weight:600;
  margin-bottom:16px;
}

.btn{
  min-height:44px;
  padding:0 32px;
  border:none;
  border-radius:8px;
  background:#4F46E5;
  color:#fff;
  font-size:1rem;
  font-weight:600;
  cursor:pointer;
  transition:background .2s;
}

.btn:hover{
  background:#4338CA;
}

#next-piece{
  display:block;
  background:#0f172a;
  border-radius:8px;
}

.mobile-controls{
  display:none;
  justify-content:center;
  align-items:center;
  gap:8px;
  margin-top:24px;
  flex-wrap:wrap;
}

.ctrl-btn{
  min-width:60px;
  min-height:60px;
  border:1px solid #e2e8f0;
  border-radius:12px;
  background:#fff;
  font-size:1.25rem;
  font-weight:600;
  color:#0f172a;
  cursor:pointer;
  box-shadow:0 1px 3px rgba(0,0,0,.06);
  -webkit-user-select:none;
  user-select:none;
  touch-action:manipulation;
}

.ctrl-btn:active{
  background:#4F46E5;
  color:#fff;
}

.ctrl-btn.wide{
  min-width:130px;
}

@media(max-width:768px){
  .game-layout{
    flex-direction:column;
    align-items:center;
  }
  .side-panel{
    flex-direction:row;
    flex-wrap:wrap;
    justify-content:center;
    min-width:auto;
  }
  .left-panel{
    order:0;
  }
  .board-wrapper{
    order:1;
  }
  .right-panel{
    order:2;
  }
  .controls-info{
    display:none;
  }
  .mobile-controls{
    display:flex;
  }
  #board{
    width:250px;
    height:500px;
  }
  .board-wrapper{
    width:254px;
  }
}
